import csv
with open('inputs/eurostat/indicator_descriptions.csv', 'r') as f:
    reader = csv.DictReader(f)
    by_theme = {}
    for row in reader:
        theme = row['theme']
        if theme not in by_theme:
            by_theme[theme] = []
        by_theme[theme].append((row['indicator_id'], row['indicator_name'], row['expected_direction']))

    for theme in ['mobility', 'population_density', 'environment', 'living_conditions']:
        print(f'=== {theme} ({len(by_theme.get(theme, []))} indicators) ===')
        for ind_id, name, direction in by_theme.get(theme, [])[:10]:
            print(f'  {ind_id}: {name[:60]}... [{direction}]')
        print()
""}

